import "errors"
import "item-storage"
import "messages"

const ITEM_MIN_STORAGE_RESERVE = ton("0.05")

contract NftItem {
    author: "Hoppr"
    version: "1.0.0"
    description: "Hoppr Genesis TEP-62 NFT item"
    incomingMessages: AllowedMessageToNftItem
    storage: NftItemStorage
    storageAtDeployment: NftItemStorageNotInitialized
}

type AllowedMessageToNftItem = AskToChangeOwnership | RequestStaticData

fun onInternalMessage(in: InMessage) {
    var loading = NftItemStorage.startLoading();
    if (loading.isNotInitialized()) {
        assert (
            in.senderAddress == loading.collectionAddress
        ) throw HopprErrors.ItemNotFromCollection;
        val init = NftItemInitAtDeployment.fromSlice(in.body);
        NftItemStorage {
            itemIndex: loading.itemIndex,
            collectionAddress: loading.collectionAddress,
            ownerAddress: init.ownerAddress,
            content: init.content,
        }.save();
        return;
    }

    var storage = loading.endLoading();
    val msg = lazy AllowedMessageToNftItem.fromSlice(in.body);
    match (msg) {
        AskToChangeOwnership => {
            assert (in.senderAddress == storage.ownerAddress) throw HopprErrors.ItemNotOwner;
            assert (
                msg.newOwnerAddress.getWorkchain() == BASECHAIN
            ) throw HopprErrors.ItemInvalidWorkchain;

            val (payloadBits, payloadRefs) = msg.forwardPayload.remainingBitsAndRefsCount();
            assert (payloadBits != 0) throw HopprErrors.ItemInvalidPayload;
            if (msg.forwardPayload.preloadUint(1) != 0) {
                assert (payloadBits == 1 && payloadRefs == 1) throw HopprErrors.ItemInvalidPayload;
            }

            val fwdFee = in.originalForwardFee;
            var rest = contract.getOriginalBalance() - ITEM_MIN_STORAGE_RESERVE;
            if (msg.forwardTonAmount != 0) {
                rest -= msg.forwardTonAmount + fwdFee;
            }
            if (msg.sendExcessesTo != null) {
                assert (
                    msg.sendExcessesTo.getWorkchain() == BASECHAIN
                ) throw HopprErrors.ItemInvalidWorkchain;
                rest -= fwdFee;
            }
            assert (rest >= 0) throw HopprErrors.ItemInsufficientValue;

            val previousOwner = storage.ownerAddress;
            storage.ownerAddress = msg.newOwnerAddress;
            storage.save();

            if (msg.forwardTonAmount != 0) {
                val ownershipNotification = createMessage({
                    bounce: BounceMode.NoBounce,
                    dest: msg.newOwnerAddress,
                    value: msg.forwardTonAmount,
                    body: NotificationForNewOwner {
                        queryId: msg.queryId,
                        oldOwnerAddress: previousOwner,
                        payload: msg.forwardPayload,
                    },
                });
                ownershipNotification.send(SEND_MODE_PAY_FEES_SEPARATELY);
            }
            if (msg.sendExcessesTo != null) {
                val excessesMessage = createMessage({
                    bounce: BounceMode.NoBounce,
                    dest: msg.sendExcessesTo,
                    value: rest,
                    body: ReturnExcessesBack { queryId: msg.queryId },
                });
                excessesMessage.send(SEND_MODE_PAY_FEES_SEPARATELY);
            }
        }
        RequestStaticData => {
            val staticDataResponse = createMessage({
                bounce: BounceMode.NoBounce,
                dest: in.senderAddress,
                value: 0,
                body: UnsafeBodyNoRef {
                    forceInline: ResponseStaticData {
                        queryId: msg.queryId,
                        itemIndex: storage.itemIndex as uint256,
                        collectionAddress: storage.collectionAddress,
                    },
                },
            });
            staticDataResponse.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE);
        }
        else => {
            assert (in.body.isEmpty()) throw HopprErrors.InvalidMessage;
        }
    }
}

fun onBouncedMessage(_in: InMessageBounced) {}

get fun get_nft_data(): (bool, int, address, address?, cell?) {
    var loading = NftItemStorage.startLoading();
    if (loading.isNotInitialized()) {
        return (false, loading.itemIndex, loading.collectionAddress, null, null);
    }
    val storage = loading.endLoading();
    return (
        true,
        storage.itemIndex,
        storage.collectionAddress,
        storage.ownerAddress,
        storage.content as unknown as cell,
    );
}

struct NftItemStorage {
    itemIndex: uint32
    collectionAddress: address
    ownerAddress: address
    content: string
}

struct NftItemStorageNotInitialized {
    itemIndex: uint32
    collectionAddress: address
}

struct NftItemStorageLoader {
    itemIndex: uint32
    collectionAddress: address
    private rest: RemainingBitsAndRefs
}

fun NftItemStorage.startLoading(): NftItemStorageLoader {
    return NftItemStorageLoader.fromCell(contract.getData());
}

fun NftItemStorageLoader.isNotInitialized(self): bool {
    return self.rest.isEmpty();
}

fun NftItemStorageLoader.endLoading(mutate self): NftItemStorage {
    return {
        itemIndex: self.itemIndex,
        collectionAddress: self.collectionAddress,
        ownerAddress: self.rest.loadAny(),
        content: self.rest.loadAny(),
    };
}

fun NftItemStorage.save(self) {
    contract.setData(self.toCell());
}

import "quote-types"

struct NftItemInitAtDeployment {
    ownerAddress: address
    content: string
}

struct (0x484f5051) MintWithQuote {
    queryId: uint64
    quote: Cell<HopprQuote>
    signature: bits512
}

struct (0x484f5001) PauseMinting {
    queryId: uint64
}

struct (0x484f5002) UnpauseMinting {
    queryId: uint64
}

struct (0x484f5003) RotateSigner {
    queryId: uint64
    newPublicKey: uint256
}

struct (0x484f5004) RevealMetadata {
    queryId: uint64
    finalBaseUri: string
}

struct (0x484f5005) FreezeMetadata {
    queryId: uint64
}

struct (0x484f5006) PremintGiveaways {
    queryId: uint64
    quantity: uint16
}

struct (0x484f5007) TransferAdmin {
    queryId: uint64
    newAdminAddress: address
}

struct (0x484f5008) PremintTreasury {
    queryId: uint64
    quantity: uint16
}

struct (0x484f5009) SetMerkleRoot {
    queryId: uint64
    newRoot: uint256
}

/// `proof` is a forward snake. Every cell stores one 256-bit sibling hash and
/// optionally references the next proof cell. Pair hashes are sorted.
struct (0x484f500a) ClaimWhitelist {
    queryId: uint64
    snapshotBalance: uint256
    proof: cell
}

struct (0x2fcb26a2) RequestStaticData {
    queryId: uint64
}

struct (0x8b771735) ResponseStaticData {
    queryId: uint64
    itemIndex: uint256
    collectionAddress: address
}

struct (0b0) PayloadInline {
    value: RemainingBitsAndRefs
}

struct (0b1) PayloadInRef {
    value: Cell<RemainingBitsAndRefs>
}

struct (0x05138d91) NotificationForNewOwner {
    queryId: uint64
    oldOwnerAddress: address
    @abi.clientType(PayloadInline | PayloadInRef)
    payload: RemainingBitsAndRefs
}

struct (0xd53276db) ReturnExcessesBack {
    queryId: uint64
}

struct (0x5fcc3d14) AskToChangeOwnership {
    queryId: uint64
    newOwnerAddress: address
    sendExcessesTo: address?
    customPayload: cell?
    forwardTonAmount: coins
    @abi.clientType(PayloadInline | PayloadInRef)
    forwardPayload: RemainingBitsAndRefs
}

struct QuoteConsumedEvent {
    quoteHash: uint256
    firstSerial: uint32
    quantity: uint16
}

/// Canonical quote payload. The signature is intentionally outside this cell.
/// Automatic Tolk serialization is the normative encoding and is mirrored by QuoteCodec.ts.
struct HopprQuote {
    version: uint16
    networkId: int32
    mintContractAddress: address
    buyerWallet: address
    quantity: uint16
    firstSerial: uint32
    lastSerial: uint32
    tail: Cell<HopprQuoteTail>
}

struct HopprQuoteTail {
    usdTotalNanoDollars: uint64
    paymentAssetKind: uint8
    paymentAssetId: uint256
    paymentAmountBaseUnits: coins
    validFrom: uint32
    validUntil: uint32
    crypto: Cell<HopprQuoteCrypto>
}

struct HopprQuoteCrypto {
    nonce: uint256
    signerEpoch: uint32
    metadataAssignmentCommitment: uint256
}
